input.command:
python3 -c "
import json
import os
# Check if CoFoAIX appears in other product files (would indicate cross-product leakage)
products = os.listdir('DATA/products')
hits = {}
for p in products:
    if p.endswith('.json'):
        try:
            with open(f'DATA/products/{p}') as f:
                data = json.load(f)
            # Search all text for CoFoAIX
            text_blob = json.dumps(data)
            if 'CoFoAIX' in text_blob or 'cofoaix' in text_blob.lower():
                count = text_blob.lower().count('cofoaix')
                hits[p] = count
        except Exception as e:
            print(f'Error reading {p}: {e}')
print('Files containing CoFoAIX:')
for p, c in hits.items():
    print(f'  {p}: {c}')
"

